func TestTagsMatch(t *testing.T) {
	tags := []*busv1.TagValue{busv1.TagString(busv1.Tag_TOPIC, "orders"), busv1.TagInt(busv1.Tag_KIND, 5)}
	if !busv1.TagsMatch(tags, nil) {
		t.Fatal("empty filter must match")
	}
	if !busv1.TagsMatch(tags, tags) {
		t.Fatal("identical tag list must match")
	}
	if busv1.TagsMatch(tags, []*busv1.TagValue{busv1.TagEnum(busv1.Tag_KIND, 5)}) {
		t.Fatal("int 5 must not match enum 5")
	}
	if busv1.TagsMatch(tags, []*busv1.TagValue{busv1.TagString(busv1.Tag_KIND, "5")}) {
		t.Fatal("int 5 must not match string 5")
	}
	if busv1.TagsMatch(tags, []*busv1.TagValue{busv1.TagString(busv1.Tag_TOPIC, "other")}) {
		t.Fatal("different topic must not match")
	}
}

func TestEventBusFanOut(t *testing.T) {
	broker, client := setupEventBus(t, 0)
	ctx := context.Background()
	ordersStream, err := busv1.SubscribeEvents(ctx, client, []*busv1.TagValue{busv1.TagString(busv1.Tag_TOPIC, "orders")})
	if err != nil {
		t.Fatal(err)
	}
	orders := collectEvents(ordersStream)
	allStream, err := busv1.SubscribeEvents(ctx, client, nil)
	if err != nil {
		t.Fatal(err)
	}
	all := collectEvents(allStream)
	waitForEventBus(t, func() bool { return broker.Stats().Subscribers == 2 }, "two subscribers")

	seq, err := busv1.PublishEvent(ctx, client, []*busv1.TagValue{busv1.TagString(busv1.Tag_TOPIC, "orders")}, []byte("o1"), "test")
	if err != nil || seq != 1 {
		t.Fatalf("publish 1: seq=%d err=%v", seq, err)
	}
	seq, err = busv1.PublishEvent(ctx, client, []*busv1.TagValue{busv1.TagString(busv1.Tag_TOPIC, "other")}, []byte("x1"), "test")
	if err != nil || seq != 2 {
		t.Fatalf("publish 2: seq=%d err=%v", seq, err)
	}
	got := orders.next(t)
	if string(got.Payload) != "o1" || got.PublisherId != "test" {
		t.Fatalf("orders event = %+v", got)
	}
	if first, second := all.next(t), all.next(t); first.Seq != 1 || second.Seq != 2 {
		t.Fatalf("all seqs = %d, %d", first.Seq, second.Seq)
	}
}

func TestEventBusKindsNeverCrossMatch(t *testing.T) {
	broker, client := setupEventBus(t, 0)
	ctx := context.Background()
	stream, err := busv1.SubscribeEvents(ctx, client, []*busv1.TagValue{busv1.TagInt(busv1.Tag_KIND, 5)})
	if err != nil {
		t.Fatal(err)
	}
	got := collectEvents(stream)
	waitForEventBus(t, func() bool { return broker.Stats().Subscribers == 1 }, "one subscriber")
	if _, err := busv1.PublishEvent(ctx, client, []*busv1.TagValue{busv1.TagString(busv1.Tag_KIND, "5")}, []byte("s"), ""); err != nil {
		t.Fatal(err)
	}
	if _, err := busv1.PublishEvent(ctx, client, []*busv1.TagValue{busv1.TagEnum(busv1.Tag_KIND, 5)}, []byte("e"), ""); err != nil {
		t.Fatal(err)
	}
	seq, err := busv1.PublishEvent(ctx, client, []*busv1.TagValue{busv1.TagInt(busv1.Tag_KIND, 5)}, []byte("i"), "")
	if err != nil || seq != 3 {
		t.Fatalf("publish 3: seq=%d err=%v", seq, err)
	}
	if event := got.next(t); string(event.Payload) != "i" {
		t.Fatalf("payload = %q, want only the int-kind event", event.Payload)
	}
}

