func TestEventBusSlowSubscriberDropsOldest(t *testing.T) {
	broker := busv1.NewEventBusBroker()
	broker.QueueCapacity = 4
	sub := broker.SubscribeLocal(nil)
	for i := 1; i <= 6; i++ {
		broker.PublishEvent(nil, []byte("m"+string(rune('0'+i))), "")
	}
	if dropped := broker.Stats().Dropped; dropped != 2 {
		t.Fatalf("dropped = %d, want 2", dropped)
	}
	if dropped := sub.Dropped(); dropped != 2 {
		t.Fatalf("subscription dropped = %d, want 2", dropped)
	}
	for want := uint64(3); want <= 6; want++ {
		event, err := sub.Recv(context.Background())
		if err != nil {
			t.Fatal(err)
		}
		if event.Seq != want {
			t.Fatalf("seq = %d, want %d", event.Seq, want)
		}
	}
	sub.Close()
	if got := broker.Stats().Subscribers; got != 0 {
		t.Fatalf("subscribers = %d after Close, want 0", got)
	}
}

