func TestEventBusGitLogRoundTrip(t *testing.T) {
	repo := filepath.Join(t.TempDir(), "log")
	broker := busv1.NewEventBusBroker()
	events := []*busv1.Event{
		broker.PublishEvent([]*busv1.TagValue{busv1.TagString(busv1.Tag_TOPIC, "orders")}, []byte("o1"), "test"),
		broker.PublishEvent([]*busv1.TagValue{busv1.TagString(busv1.Tag_TOPIC, "other")}, []byte("x1"), "test"),
		broker.PublishEvent([]*busv1.TagValue{busv1.TagString(busv1.Tag_TOPIC, "orders")}, []byte("o2"), "test"),
	}
	head1, err := busv1.ExportEventsToGit(repo, events, busv1.EventLogBranch)
	if err != nil {
		t.Fatal(err)
	}
	count, err := exec.Command("git", "-C", repo, "rev-list", "--count", busv1.EventLogBranch).Output()
	if err != nil {
		t.Fatal(err)
	}
	if strings.TrimSpace(string(count)) != "3" {
		t.Fatalf("commit count = %s, want 3", count)
	}
	head2, err := busv1.ExportEventsToGit(repo, events, busv1.EventLogBranch)
	if err != nil {
		t.Fatal(err)
	}
	if head2 != head1 {
		t.Fatalf("re-export not idempotent: %s != %s", head2, head1)
	}
	all, err := busv1.ImportEventsFromGit(repo, busv1.EventLogBranch, nil, 0, 0)
	if err != nil {
		t.Fatal(err)
	}
	if len(all) != 3 || all[0].Seq != 1 || all[1].Seq != 2 || all[2].Seq != 3 {
		t.Fatalf("imported = %+v", all)
	}
	for i, want := range []string{"o1", "x1", "o2"} {
		if string(all[i].Payload) != want || all[i].PublisherId != "test" {
			t.Fatalf("event %d = %+v", i, all[i])
		}
	}
	orders, err := busv1.ImportEventsFromGit(repo, busv1.EventLogBranch, []*busv1.TagValue{busv1.TagString(busv1.Tag_TOPIC, "orders")}, 0, 0)
	if err != nil {
		t.Fatal(err)
	}
	if len(orders) != 2 || orders[0].Seq != 1 || orders[1].Seq != 3 {
		t.Fatalf("orders = %+v", orders)
	}
	window, err := busv1.ImportEventsFromGit(repo, busv1.EventLogBranch, nil, 1, 2)
	if err != nil {
		t.Fatal(err)
	}
	if len(window) != 1 || window[0].Seq != 2 {
		t.Fatalf("window = %+v", window)
	}
	if _, err := os.Stat(filepath.Join(repo, ".git")); err != nil {
		t.Fatal(err)
	}
}
